//laço numerico: FOR
const input = require('readline-sync')
//poderia ser escrito acumulador += 1 ou acumulador++
console.clear
let nota;
let soma = 0
for (let i = 1; i <= 3; i++) {
    //console.log('Repetição', i)
    nota = Number(input.question(`Informe a nota ${i} do aluno: `))
    soma = soma + nota
}
console.log(`A media do aluno é ${soma / 3}`)
